import{_ as t,c as o,a2 as e,o as a}from"./chunks/framework.CqbvlPrP.js";const q=JSON.parse('{"title":"第六章：重要教法：四正勤，五根，五力","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/佛陀传奇/第六章：重要教法：四正勤，五根，五力.md","filePath":"meditation/佛陀传奇/第六章：重要教法：四正勤，五根，五力.md"}'),_={name:"meditation/佛陀传奇/第六章：重要教法：四正勤，五根，五力.md"};function r(n,p,i,s,u,d){return a(),o("div",null,p[0]||(p[0]=[e('<h1 id="第六章-重要教法-四正勤-五根-五力" tabindex="-1">第六章：重要教法：四正勤，五根，五力 <a class="header-anchor" href="#第六章-重要教法-四正勤-五根-五力" aria-label="Permalink to &quot;第六章：重要教法：四正勤，五根，五力&quot;">​</a></h1><p>《佛陀传奇：从皇宫到涅槃的光明之路》</p><p>6.16四正勤（相应部49相应1-12经/东方等十二经(正勤相应/大篇/修多罗)）</p><p>&quot;如是我闻，一时佛在舍卫城。在那里，世尊对比丘们说道：&#39;诸比丘，有四种正勤。是哪四种呢？</p><p>在此，比丘为了防止尚未生起的恶不善法生起，生起欲望，精进努力，激发精进，策励其心，精勤修习。</p><p>为了断除已经生起的恶不善法，生起欲望，精进努力，激发精进，策励其心，精勤修习。</p><p>为了令尚未生起的善法生起，生起欲望，精进努力，激发精进，策励其心，精勤修习。</p><p>为了令已生起的善法安住、不忘失、增长、广大、修习圆满，生起欲望，精进努力，激发精进，策励其心，精勤修习。</p><p>诸比丘，这就是四种正勤。&#39;&quot;</p><p>&quot;诸比丘，就像恒河向东流、倾向东方、趣向东方；同样地，诸比丘，修习四正勤、多修习四正勤的比丘，必定向涅槃流、倾向涅槃、趣向涅槃。诸比丘，比丘如何修习四正勤、多修习四正勤而向涅槃流、倾向涅槃、趣向涅槃呢？在此，比丘为了防止尚未生起的恶不善法生起......（重复上述四种正勤的内容）......诸比丘，这就是比丘如何通过修习与多修习四正勤而向涅槃流、倾向涅槃、趣向涅槃。&quot;</p><p>第十二经</p><p>6.17正勤经（增支部4集13经/勤奋经）</p><p>&quot;诸比丘，有四种正勤。是哪四种呢？</p><p>在此，比丘：</p><p>为防止未生起的恶不善法生起，生起欲望，精进努力，激发精进，策励其心，精勤修习；</p><p>为断除已生起的恶不善法，生起欲望，精进努力，激发精进，策励其心，精勤修习；</p><p>为令未生起的善法生起，生起欲望，精进努力，激发精进，策励其心，精勤修习；</p><p>为令已生起的善法住立、不忘失、增长、广大、修习、圆满，生起欲望，精进努力，激发精进，策励其心，精勤修习。</p><p>诸比丘，这就是四种正勤。&quot;</p><p>偈颂：</p><p>&quot;正勤能克服魔境，</p><p>已度脱生死怖畏。</p><p>欢喜战胜魔军已，无动摇，</p><p>超越一切魔军力，得安乐。&quot;</p><p>第三经。</p><p>6.18五根（相应部48相应10经/第二分别经(根相应/大篇/修多罗)）</p><p>&quot;诸比丘，有这五根。是哪五根呢？信根，精进根，念根，定根，慧根。</p><p>诸比丘，什么是信根？在此，诸比丘，圣弟子具足信心，信仰如来的觉悟——&#39;世尊确实是阿罗汉、正等正觉者、明行具足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊&#39;——诸比丘，这称为信根。</p><p>诸比丘，什么是精进根？在此，诸比丘，圣弟子为断除不善法、成就善法而住于精进，具足力量、坚固精进、于善法中不舍责任。他为防止未生起的恶不善法生起，生起欲望，精进努力，发起精进，策励其心，精勤；为断除已生起的恶不善法...为令未生起的善法生起...为令已生起的善法住立、不忘失、增长、广大、修习、圆满，生起欲望，精进努力，发起精进，策励其心，精勤——诸比丘，这称为精进根。</p><p>诸比丘，什么是念根？在此，诸比丘，圣弟子具足最上的念和觉知，能忆念、随忆久远之事与言说。他以热诚、正知、正念住于身随观身，于世间舍离贪忧；于受...于心...于法随观法而住，以热诚、正知、正念，于世间舍离贪忧——诸比丘，这称为念根。</p><p>诸比丘，什么是定根？在此，诸比丘，圣弟子以舍为所缘，获得定，获得心一境性。他离诸欲、离不善法，有寻有伺，由离生喜乐，成就初禅而住。寻伺寂灭，内心清净，心专一性，无寻无伺，由定生喜乐，成就第二禅而住。离喜而住，具念正知，以身感受乐，如圣者所说的&#39;舍念乐住&#39;，成就第三禅而住。舍乐及苦，先前已灭喜忧，不苦不乐，具足舍念清净，成就第四禅而住——诸比丘，这称为定根。</p><p>诸比丘，什么是慧根？在此，诸比丘，圣弟子具足通达生灭的智慧，具备圣者的洞察力，能正确导向苦的灭尽。他如实了知&#39;这是苦&#39;，如实了知&#39;这是苦集&#39;，如实了知&#39;这是苦灭&#39;，如实了知&#39;这是趣向苦灭之道&#39;——诸比丘，这称为慧根。诸比丘，这就是五根。&quot;</p><p>第十经。</p><p>6.19五力（广说经（增支部5集14经/广说经））</p><p>&quot;诸比丘，有这五种力。是哪五种呢？信力、精进力、念力、定力、慧力。</p><p>诸比丘，什么是信力？在此，诸比丘，圣弟子具足信心，信仰如来的觉悟——&#39;世尊确实是阿罗汉、正等正觉者、明行具足、善逝、世间解、无上士、调御丈夫、天人师、佛、世尊&#39;。诸比丘，这称为信力。</p><p>诸比丘，什么是精进力？在此，诸比丘，圣弟子为断除不善法、成就善法而住于精进，具足力量、坚固精进、于善法中不舍责任。诸比丘，这称为精进力。</p><p>诸比丘，什么是念力？在此，诸比丘，圣弟子具足念，成就最上的念和觉知，能忆念、随忆久远之事与言说。诸比丘，这称为念力。</p><p>诸比丘，什么是定力？在此，诸比丘，圣弟子离诸欲、离不善法，有寻有伺，由离生喜乐，成就初禅而住。寻伺寂灭，内心清净，心专一性，无寻无伺，由定生喜乐，成就第二禅而住。离喜而住，具念正知，以身感受乐，如圣者所说的&#39;舍念乐住&#39;，成就第三禅而住。舍乐及苦，先前已灭喜忧，不苦不乐，具足舍念清净，成就第四禅而住。诸比丘，这称为定力。</p><p>诸比丘，什么是慧力？在此，诸比丘，圣弟子具足通达生灭的智慧，具备圣者的洞察力，能正确导向苦的灭尽。诸比丘，这称为慧力。诸比丘，这就是五力。&quot;</p><p>第四经。</p>',41)]))}const l=t(_,[["render",r]]);export{q as __pageData,l as default};
